new_account <- function(owner, balance = 0) {
  structure(list(owner = owner, balance = balance), class = "account")
}
deposit <- function(acc, amount) {
  acc$balance <- acc$balance + amount
  acc
}
withdraw <- function(acc, amount) {
  if (amount > acc$balance) stop("잔액 부족")
  acc$balance <- acc$balance - amount
  acc
}
balance <- function(acc) acc$balance
